import java.nio.file.*;import java.util.*;import com.google.gson.*;import io.github.r3neer.scalebrews.collision.geometry.*;import io.github.r3neer.scalebrews.collision.api.*;import io.github.r3neer.scalebrews.collision.api.spi.*;import net.minecraft.resources.Identifier;import org.joml.Matrix4f;
public final class S55CommonBody {static void check(boolean v,String why){if(!v)throw new AssertionError("S55 COMMON "+why);}public static void main(String[] args)throws Exception {io.github.r3neer.scalebrews.collision.pose.BuiltInPoseEngines.initialize();var gson=new Gson();var rows=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonArray();int parts=0,pieces=0;for(var row:rows){var geometry=gson.fromJson(row.getAsJsonObject().get("geometry"),ModelGeometry.class);check(geometry.format()==2&&ModelGeometry.matrix(geometry.modelTransform()).equals(new Matrix4f(),0),"local root changed");var engine=CollisionEngines.pose(Identifier.fromNamespaceAndPath("scalebrews","static")).orElseThrow();var bound=engine.bind(geometry,Map.of(),Set.of(),PoseEngine.Resources.empty()).orElseThrow();var rest=bound.evaluate(new PoseEngine.Inputs(5,.3f,90,20,10,true)).orElseThrow();check(rest.isEmpty(),"rest replacement");var matrices=geometry.transforms(rest);for(var p:geometry.parts()){Matrix4f expected=p.parent()==null?p.sourcePose().matrix():new Matrix4f(matrices.get(p.parent())).mul(p.sourcePose().matrix());check(matrices.get(p.id()).equals(expected,1e-6f),"local hierarchy changed");parts++;}for(var p:geometry.pieces()){check(ConvexBox.of(p.box(),matrices.get(p.part())).vertices().size()==8,"convex vertex membership");pieces++;}check(bound.evaluate(new PoseEngine.Inputs(5,.3f,0,0,0,false)).isEmpty(),"incompatible admitted");}System.out.println("S55_COMMON_DTO_PASS models="+rows.size()+" parts="+parts+" cubes="+pieces+" clientClassloading=forbidden");}}
